  var page=new TabPage("Results");foreach(var h in new[]{"CHECK","NSCP","FOOTING / STRAP","LOAD CASE","DEMAND","CAPACITY","RATIO","RESULT"})results.Columns.Add("c"+results.Columns.Count,h);results.Dock=DockStyle.Fill;var resultHost=new Panel{Dock=DockStyle.Fill,BackColor=DesignSheetForm.PaneBack};resultHost.Controls.Add(results);resultHost.Controls.Add(verdict);page.Controls.Add(resultHost);AddResultPage(page);
  foreach(var c in Inputs.Values){c.TextChanged+=(s,e)=>{if(!Restoring)Refresh0();};var combo=c as ComboBox;if(combo!=null)combo.SelectedIndexChanged+=(s,e)=>{if(!Restoring)Refresh0();};}
