 /* the STAAD table stays the one store; this grid shows and edits the rows of one support */
 void ShowSupport(string node){supportNode=node;supportTitle.Text="REACTIONS AT SUPPORT "+node+" (kN, kN·m; STAAD axes) - type or edit, or paste the whole STAAD table in the first tab";Restoring=true;try{supportReactions.Rows.Clear();List<SupportReaction> rows;try{string u;rows=TrussSupport.Reactions(reactions.Text,out u);}catch(Exception){rows=new List<SupportReaction>();}
   foreach(var r in rows.Where(x=>x.Node.Split(' ')[0].Equals(node,StringComparison.OrdinalIgnoreCase)))supportReactions.Rows.Add(r.Case,r.Fx.ToString("0.###",Inv),r.Fy.ToString("0.###",Inv),r.Fz.ToString("0.###",Inv),r.Mx.ToString("0.###",Inv),r.My.ToString("0.###",Inv),r.Mz.ToString("0.###",Inv));}finally{Restoring=false;}}
 void StoreSupportReactions(){if(supportNode=="")return;List<SupportReaction> all;try{string u;all=reactions.Text.Trim()==""?new List<SupportReaction>():TrussSupport.Reactions(reactions.Text,out u);}catch(Exception){all=new List<SupportReaction>();}
  all.RemoveAll(x=>x.Node.Split(' ')[0].Equals(supportNode,StringComparison.OrdinalIgnoreCase));
  foreach(DataGridViewRow r in supportReactions.Rows){if(r.IsNewRow)continue;string lc=Convert.ToString(r.Cells["Case"].Value).Trim();if(lc=="")continue;Func<string,double> n=k=>{double v;double.TryParse(Convert.ToString(r.Cells[k].Value,Inv),NumberStyles.Float,Inv,out v);return v;};all.Add(new SupportReaction{Node=supportNode,Case=lc,Fx=n("Fx"),Fy=n("Fy"),Fz=n("Fz"),Mx=n("Mx"),My=n("My"),Mz=n("Mz")});}
  var b=new StringBuilder(ExampleReactions);foreach(var r in all.OrderBy(x=>x.Case,StringComparer.Ordinal).ThenBy(x=>x.Node,StringComparer.Ordinal))b.Append(r.Node.Split(' ')[0]).Append('\t').Append(r.Case).Append('\t').Append(string.Join("\t",new[]{r.Fx,r.Fy,r.Fz,r.Mx,r.My,r.Mz}.Select(v=>v.ToString("0.###",Inv)))).Append('\n');
  Restoring=true;try{reactions.Text=b.ToString();}finally{Restoring=false;}Refresh0();}
 static readonly string ExampleReactions="Node\tL/C\tHorizontal Fx kN\tVertical Fy kN\tHorizontal Fz kN\tMoment Mx kNm\tMoment My kNm\tMoment Mz kNm\n";
 void Fill(string reactionsText,IEnumerable<string[]> foots,IEnumerable<string[]> strapRows){supportNode="";Restoring=true;try{reactions.Text=reactionsText;footings.Rows.Clear();foreach(var f in foots)footings.Rows.Add(f);straps.Rows.Clear();foreach(var s in strapRows)straps.Rows.Add(s);}finally{Restoring=false;}Refresh0();}
 /* sample: exterior column at a property line (footing pushed 0.60 m inward) strapped to an interior column 6 m away */
 internal void ExampleOne(){Fill(ExampleReactions+"1\t1 DL+LL\t0\t600\t0\t0\t0\t0\n2\t1 DL+LL\t0\t900\t0\t0\t0\t0\n1\t2 1.2DL+1.6LL\t0\t820\t0\t0\t0\t0\n2\t2 1.2DL+1.6LL\t0\t1240\t0\t0\t0\t0\n",
  new[]{new[]{"1","0","0","400","400","1.6","2.8","600","0.6","0","Auto","16@150"},new[]{"2","6","0","400","400","2.6","2.6","600","0","0","Auto","16@150"}},new[]{new[]{"1","2","400","800","4-25","3-20","10@150"}});}
 /* sample: corner column with the footing off-centre both ways, strapped along X and along Z */
 internal void ExampleCorner(){Fill(ExampleReactions+"1\t1 DL+LL\t0\t300\t0\t0\t0\t0\n2\t1 DL+LL\t0\t800\t0\t0\t0\t0\n3\t1 DL+LL\t0\t750\t0\t0\t0\t0\n1\t2 1.2DL+1.6LL\t0\t420\t0\t0\t0\t0\n2\t2 1.2DL+1.6LL\t0\t1100\t0\t0\t0\t0\n3\t2 1.2DL+1.6LL\t0\t1030\t0\t0\t0\t0\n",
  new[]{new[]{"1","0","0","400","400","2.2","2.2","600","0.9","0.9","Auto","16@150"},new[]{"2","6","0","400","400","2.6","2.6","600","0","0","Auto","16@150"},new[]{"3","0","5","400","400","2.6","2.6","600","0","0","Auto","16@150"}},
  new[]{new[]{"1","2","450","900","6-25","3-20","10@125"},new[]{"1","3","450","900","6-25","3-20","10@125"}});}
 void AddNodes(){string u;var rows=Rows(out u);var have=new HashSet<string>(footings.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow).Select(r=>Convert.ToString(r.Cells["Node"].Value)),StringComparer.OrdinalIgnoreCase);Restoring=true;try{foreach(var n in rows.Select(r=>r.Node.Split(' ')[0]).Distinct())if(have.Add(n))footings.Rows.Add(n,"0","0","400","400","1.5","1.5","500","0","0","Auto","16@150");}finally{Restoring=false;}Refresh0();}
 /* STAAD Nodes table (node, X, Y, Z in metres): fills the plan coordinates of the footings */
 void PasteCoordinates(){if(!Clipboard.ContainsText())throw new Exception("Copy the STAAD Nodes table (node, X, Y, Z) first.");int set=0;bool zUp=Value("Vertical")=="Z";Restoring=true;try{foreach(var line in Clipboard.GetText().Split('\n')){var cells=line.Split(new[]{'\t',',',' '},StringSplitOptions.RemoveEmptyEntries);double x,y,z;if(cells.Length<4||!double.TryParse(cells[1],NumberStyles.Float,Inv,out x)||!double.TryParse(cells[2],NumberStyles.Float,Inv,out y)||!double.TryParse(cells[3],NumberStyles.Float,Inv,out z))continue;
   foreach(DataGridViewRow r in footings.Rows){if(r.IsNewRow||!string.Equals(Convert.ToString(r.Cells["Node"].Value),cells[0],StringComparison.OrdinalIgnoreCase))continue;r.Cells["X"].Value=x.ToString("0.###",Inv);r.Cells["Z"].Value=(zUp?y:z).ToString("0.###",Inv);set++;}}}finally{Restoring=false;}if(set==0)throw new Exception("No footing node was found in the copied table.");Refresh0();}
 static double Num(DataGridViewRow r,string col,string what){double v;string s=Convert.ToString(r.Cells[col].Value,Inv).Trim();if(!double.TryParse(s,NumberStyles.Float,Inv,out v))throw new Exception(what+" row "+(r.Index+1)+": enter "+r.DataGridView.Columns[col].HeaderText.ToLowerInvariant()+" as a number.");return v;}
 internal StrapInput Input(){var i=new StrapInput{Fc=Number("Fc"),Fy=Number("Fy"),Fyt=Number("Fyt"),Cover=Number("Cover"),StrapCover=Number("StrapCover"),Qa=Number("Qa"),Df=Number("Df"),GammaSoil=Number("GammaSoil"),GammaConc=Number("GammaConc"),SupportHeight=Number("SupportHeight"),Friction=Number("Friction"),SlidingFS=Number("SlidingFS"),OverturningFS=Number("OverturningFS"),Aggregate=Number("Aggregate"),Vertical=Value("Vertical")};
  var fac=Value("Factored").Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).Where(x=>x!="").ToList();var ser=Value("Service").Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).Where(x=>x!="").ToList();
  Func<string,List<string>,bool> listed=(c,list)=>list.Any(x=>c.Equals(x,StringComparison.OrdinalIgnoreCase)||c.Split(' ')[0].Equals(x,StringComparison.OrdinalIgnoreCase));
  var split=FactoredCases();i.Factored=c=>split.Count>0?split.Contains(c):fac.Count>0?listed(c,fac):ser.Count>0?!listed(c,ser):StrapFooting.LooksFactored(c);
  foreach(DataGridViewRow r in footings.Rows){if(r.IsNewRow)continue;string node=Convert.ToString(r.Cells["Node"].Value).Trim();if(node=="")continue;i.Nodes.Add(new StrapNode{Node=node,X=Num(r,"X","Footings"),Z=Num(r,"Z","Footings"),Cx=Num(r,"Cx","Footings")/1000,Cz=Num(r,"Cz","Footings")/1000,B=Num(r,"B","Footings"),L=Num(r,"L","Footings"),T=Num(r,"T","Footings")/1000,Ex=Num(r,"Ex","Footings"),Ez=Num(r,"Ez","Footings"),Mode=Convert.ToString(r.Cells["Mode"].Value)==""?"Auto":Convert.ToString(r.Cells["Mode"].Value),Bars=Convert.ToString(r.Cells["Bars"].Value)});}
  foreach(DataGridViewRow r in straps.Rows){if(r.IsNewRow)continue;string a=Convert.ToString(r.Cells["From"].Value).Trim(),b=Convert.ToString(r.Cells["To"].Value).Trim();if(a==""&&b=="")continue;i.Straps.Add(new StrapBeam{From=a,To=b,Width=Num(r,"Width","Straps")/1000,Depth=Num(r,"Depth","Straps")/1000,Top=Convert.ToString(r.Cells["Top"].Value),Bottom=Convert.ToString(r.Cells["Bottom"].Value),Stirrups=Convert.ToString(r.Cells["Stirrups"].Value)});}
  return i;}
 internal List<SupportReaction> Rows(out string unit){unit="";var service=new List<SupportReaction>();if(reactions.Text.Trim()!="")service=TrussSupport.Reactions(reactions.Text,out unit);if(factoredReactions.Text.Trim()=="")return service;
  string u2;var fac=TrussSupport.Reactions(factoredReactions.Text,out u2);if(unit=="")unit=u2;var names=new HashSet<string>(service.Select(r=>r.Case),StringComparer.OrdinalIgnoreCase);foreach(var r in fac)if(names.Contains(r.Case))r.Case=r.Case+" (factored)";return service.Concat(fac).ToList();}
 /* load cases of the factored table (empty when only one table is used) */
 HashSet<string> FactoredCases(){var set=new HashSet<string>(StringComparer.OrdinalIgnoreCase);if(factoredReactions.Text.Trim()=="")return set;string u;try{foreach(var r in Rows(out u).Skip(reactions.Text.Trim()==""?0:TrussSupport.Reactions(reactions.Text,out u).Count))set.Add(r.Case);}catch(Exception){}return set;}
 /* the plan and results follow the inputs once the grids have settled (a grid shown for the first time raises its own events) */
 readonly Timer settle=new Timer{Interval=150};bool settleHooked;
 void Refresh0(){if(!IsHandleCreated){RefreshNow();return;}if(!settleHooked){settleHooked=true;settle.Tick+=(s,e)=>{settle.Stop();RefreshNow();};FormClosed+=(s,e)=>settle.Dispose();}settle.Stop();settle.Start();}
 void RefreshNow(){results.Rows.Clear();StrapInput inp=null;try{inp=Input();StrapFooting.Validate(inp);plan.Input=inp;strapSection.Input=inp;strapSection.Invalidate();if(supportNode==""&&inp.Nodes.Count>0)ShowSupport(inp.Nodes[0].Node);}catch(Exception ex){plan.Input=inp;plan.Case=null;plan.Invalidate();loaded.ForeColor=Color.Firebrick;loaded.Text=ex.Message;return;}
  plan.Case=null;plan.Failing.Clear();if(reactions.Text.Trim()==""&&factoredReactions.Text.Trim()==""){loaded.ForeColor=PowTheme.Muted;loaded.Text="No reactions yet. Paste or import the STAAD Support Reactions table.";plan.Invalidate();return;}
  try{string unit;var rows=Rows(out unit);var notes=new List<string>();var cases=StrapFooting.Cases(inp,rows,notes);var steps=new Dictionary<SupportCheck,List<string>>();var checks=StrapFooting.Check(inp,cases,notes,steps);
   foreach(var c in checks){int k=results.Rows.Add(c.Name,c.Clause,c.Node,c.Case,StrapFooting.F(c.Demand,"0.0")+" "+c.Unit,StrapFooting.F(c.Capacity,"0.0")+" "+c.Unit,StrapFooting.F(c.Ratio,"0.00"),c.Ok?"OK":"NG");if(!c.Ok){results.Rows[k].DefaultCellStyle.ForeColor=Color.Firebrick;plan.Failing.Add(c.Node);}}
   plan.Case=cases.Where(c=>!c.Factored).OrderByDescending(c=>c.Qmax.Max()).FirstOrDefault()??cases[0];int ng=checks.Count(c=>!c.Ok);
   verdict.ForeColor=ng>0?Color.Firebrick:Color.FromArgb(28,122,84);verdict.Text=(ng>0?"✕  "+ng+" of "+checks.Count+" checks do not pass - the footings and straps concerned are red in the plan":"✓  All "+checks.Count+" checks pass")+"   ·   largest ratio "+StrapFooting.F(checks.Count==0?0:checks.Max(c=>c.Ratio),"0.00");
   loaded.ForeColor=ng>0?Color.Firebrick:PowTheme.Teal;loaded.Text=rows.Count+" reaction rows; "+cases.Count(c=>!c.Factored)+" service and "+cases.Count(c=>c.Factored)+" factored load case(s) at all footings; unit "+unit+".\r\n"+(ng>0?ng+" check(s) NG - see Results (red in the plan).":"All checks pass - largest ratio "+StrapFooting.F(checks.Count==0?0:checks.Max(c=>c.Ratio),"0.00")+".")+(notes.Any(n=>n.Contains("skipped"))?"  Some load cases were skipped (see the report).":"");}
  catch(Exception ex){verdict.ForeColor=PowTheme.Muted;verdict.Text="Results appear when the inputs are complete.";loaded.ForeColor=Color.Firebrick;loaded.Text=ex.Message;}plan.Invalidate();}
 protected override void AfterRestore(){Refresh0();}
 protected override bool OptionalSavedInput(string key){return key=="FactoredReactions"||key=="Factored"||key=="Service"||key=="Friction"||key=="Aggregate"||key=="SlidingFS"||key=="OverturningFS";}
 protected override void WriteAdditionalState(System.Xml.XmlElement root){foreach(var pair in new[]{new KeyValuePair<string,DataGridView>("Footing",footings),new KeyValuePair<string,DataGridView>("Strap",straps)})foreach(DataGridViewRow r in pair.Value.Rows){if(r.IsNewRow)continue;var e=root.OwnerDocument.CreateElement(pair.Key);foreach(DataGridViewColumn c in pair.Value.Columns)e.SetAttribute(c.Name.ToLowerInvariant(),Convert.ToString(r.Cells[c.Index].Value,Inv));root.AppendChild(e);}}
 protected override void ReadAdditionalState(System.Xml.XmlElement root){foreach(var pair in new[]{new KeyValuePair<string,DataGridView>("Footing",footings),new KeyValuePair<string,DataGridView>("Strap",straps)}){pair.Value.Rows.Clear();foreach(System.Xml.XmlElement e in root.SelectNodes(pair.Key)){int i=pair.Value.Rows.Add();foreach(DataGridViewColumn c in pair.Value.Columns){string v=e.GetAttribute(c.Name.ToLowerInvariant());var combo=c as DataGridViewComboBoxColumn;if(combo!=null&&!combo.Items.Contains(v))continue;pair.Value.Rows[i].Cells[c.Index].Value=v;}}}}
 /* ---------- report ---------- */
 protected override CalculationDocument BuildDocument(){var inp=Input();string unit;var rows=Rows(out unit);var notes=new List<string>();var cases=StrapFooting.Cases(inp,rows,notes);var steps=new Dictionary<SupportCheck,List<string>>();var checks=StrapFooting.Check(inp,cases,notes,steps);Func<double,string> f1=v=>StrapFooting.F(v,"0.0");Func<double,string> f2=v=>StrapFooting.F(v,"0.00");string q=inp.Vertical=="Z"?"Y":"Z";
  var r=new RichReport("Strap Foundation - Design Calculation");
  r.Heading("1  DESIGN BASIS").Paragraph("NSCP 2015 (ACI 318-14): Section 413 footings, 409 beams (strap), 422 shear and punching. STAAD support reactions in the STAAD global axes, "+inp.Vertical+" vertical (plan X-"+q+"). Footings and straps are rigid; the straps are clear of the soil. At a footing whose moment goes to the straps, the strap end moments make the soil pressure as uniform as the straps allow (two straps in different directions: uniform; one strap: the part across the strap stays with the footing). A footing whose moment goes to the footing is the fulcrum of the strap. Each strap carries a constant shear S = (Mi + Mj) / L between the columns. Service load cases check bearing (gross, with the footing, soil and strap weights); factored load cases design the footings and straps (net pressure).");
  r.Heading("2  MATERIALS, SOIL AND LOAD CASES").KeyValues(new[]{new[]{"Concrete fc'",f1(inp.Fc)+" MPa, "+f1(inp.GammaConc)+" kN/m³"},new[]{"Reinforcement","fy "+f1(inp.Fy)+" MPa, stirrups fyt "+f1(inp.Fyt)+" MPa"},new[]{"Cover","footing bottom "+StrapFooting.F(inp.Cover,"0")+" mm, strap "+StrapFooting.F(inp.StrapCover,"0")+" mm"},new[]{"Soil","qa (gross) "+f1(inp.Qa)+" kPa; Df "+f2(inp.Df)+" m; γs "+f1(inp.GammaSoil)+" kN/m³"},new[]{"STAAD support","at "+f2(inp.SupportHeight)+" m above the footing base (lever of the horizontal reactions)"},new[]{"Service load cases",string.Join(", ",cases.Where(c=>!c.Factored).Select(c=>c.Case))},new[]{"Factored load cases",string.Join(", ",cases.Where(c=>c.Factored).Select(c=>c.Case))}});
  r.Heading("3  FOOTINGS AND STRAPS").Table(new[]{"Footing","Node X, "+q+" (m)","Column (mm)","B x L x T","ex, e"+q.ToLowerInvariant()+" (m)","Moment to","Bars"},inp.Nodes.Select(n=>new[]{"F"+n.Node,f2(n.X)+", "+f2(n.Z),StrapFooting.F(n.Cx*1000,"0")+" x "+StrapFooting.F(n.Cz*1000,"0"),f2(n.B)+" x "+f2(n.L)+" x "+StrapFooting.F(n.T*1000,"0"),f2(n.Ex)+", "+f2(n.Ez),n.ToStraps(inp.Straps.Count(s=>s.From==n.Node||s.To==n.Node))?"straps":"footing",n.Bars}),new float[]{9,15,12,18,13,10,10});
  r.Table(new[]{"Strap","Direction","L (m)","b x h (mm)","Top","Bottom","Stirrups"},inp.Straps.Select(s=>{var a=inp.Nodes[StrapFooting.Index(inp,s.From)];var b=inp.Nodes[StrapFooting.Index(inp,s.To)];double L=StrapFooting.Length(a,b);double ang=Math.Atan2(b.Z-a.Z,b.X-a.X)*180/Math.PI;return new[]{"S"+s.From+"-"+s.To,StrapFooting.F(ang,"0.0")+"° from +X",f2(L),StrapFooting.F(s.Width*1000,"0")+" x "+StrapFooting.F(s.Depth*1000,"0"),s.Top,s.Bottom,s.Stirrups};}),new float[]{12,18,10,16,14,14,16});
  var gov=cases.Where(c=>!c.Factored).OrderByDescending(c=>c.Qmax.Max()).FirstOrDefault()??cases[0];var failing=new HashSet<string>(checks.Where(c=>!c.Ok).Select(c=>c.Node));
  r.Figure(420,(g,rect)=>StrapDrawing.Plan(g,rect,inp,gov,7.5f,failing),"Figure 1 - Plan in the STAAD axes: footings, columns, straps, eccentricities; soil reaction and pressure for load case "+gov.Case+". Red: a failing check.");
  r.Figure(300,(g,rect)=>StrapVisuals.Iso(g,rect,inp,failing,7.5f,gov,new View3D()),"Figure 2 - 3D view of the foundation in the STAAD axes; footing tops coloured by the soil pressure of load case "+gov.Case+".");
  r.Figure(300,(g,rect)=>StrapVisuals.Iso(g,rect,inp,failing,7.5f,null,new View3D{Rebar=true,Yaw=35,Pitch=30}),"Figure 3 - Reinforcement: footing bottom mesh both ways, strap top and bottom bars and stirrups (concrete shown see-through).");
  r.Heading("4  STAAD SUPPORT REACTIONS ("+unit+")").Table(new[]{"Node","Load case","Type","Fx","Fy","Fz","Mx","My","Mz"},rows.Where(x=>cases.Any(c=>c.Case==x.Case)&&inp.Nodes.Any(n=>n.Node.Equals(x.Node.Split(' ')[0],StringComparison.OrdinalIgnoreCase))).Select(x=>new[]{x.Node,x.Case,inp.Factored(x.Case)?"factored":"service",f1(x.Fx),f1(x.Fy),f1(x.Fz),f1(x.Mx),f1(x.My),f1(x.Mz)}),new float[]{8,22,10,10,10,10,10,10,10});
  r.Heading("5  STATICS PER LOAD CASE").Table(new[]{"Load case","Footing","P column (kN)","R soil (kN)","q avg (kPa)","q max (kPa)","q min (kPa)"},cases.SelectMany(c=>inp.Nodes.Select((n,k)=>new[]{c.Case+(c.Factored?" (net)":""),"F"+n.Node,f1(c.P[k]),f1(c.R[k]),f1(c.Qavg[k]),f1(c.Qmax[k]),f1(c.Qmin[k])})),new float[]{26,10,13,13,13,13,12},row=>{double v;return double.TryParse(row[6],NumberStyles.Float,Inv,out v)&&v<0?(Color?)Color.FromArgb(252,232,232):null;});
  if(inp.Straps.Count>0)r.Table(new[]{"Load case","Strap","Shear S (kN)","M at "+"start (kN·m)","M at end (kN·m)"},cases.SelectMany(c=>inp.Straps.Select((s,k)=>new[]{c.Case,"S"+s.From+"-"+s.To,f1(c.Shear[k]),f1(-c.MuA[k]),f1(c.MuB[k])})),new float[]{30,16,18,18,18});
  r.Paragraph("Strap moments: sagging positive (bottom tension), hogging negative; start = the FROM column. Factored cases use net pressures (the footing and soil weights are not included).",true);
  for(int s=0;s<inp.Straps.Count;s++){int k=s;r.Figure(210,(g,rect)=>StrapVisuals.StrapSection(g,rect,inp,inp.Straps[k],7.5f),"Strap S"+inp.Straps[s].From+"-"+inp.Straps[s].To+" section: bars in their layers, spacer bars between layers, stirrups.");r.Figure(290,(g,rect)=>StrapDrawing.Strap(g,rect,inp,k,cases,7.5f),"Figure "+(4+s)+" - Strap S"+inp.Straps[s].From+"-"+inp.Straps[s].To+": elevation, factored moment and shear envelopes.");}
  r.Heading("6  FOOTING DETAILS");foreach(var n0 in inp.Nodes){var n=n0;r.Figure(230,(g,rect)=>StrapVisuals.Footing(g,rect,inp,n,7.5f));}
  r.Heading("7  DESIGN CHECKS");foreach(var c in checks){List<string> lines;if(!steps.TryGetValue(c,out lines))lines=new List<string>();r.Check(c.Name,c.Clause,lines,c.Node+(c.Case=="-"?"":", load case "+c.Case),c.Demand,c.Capacity,c.Unit,c.Ok);}
  r.Heading("8  SUMMARY").Table(new[]{"Check","Clause","Item / L/C","Demand","Capacity","Ratio","Result"},checks.Select(c=>new[]{c.Name,c.Clause,c.Node+" / "+c.Case,f1(c.Demand)+" "+c.Unit,f1(c.Capacity)+" "+c.Unit,StrapFooting.F(c.Ratio,"0.00"),c.Ok?"OK":"NOT OK"}),new float[]{28,12,16,13,13,8,9},row=>row[6]=="OK"?null:(Color?)Color.FromArgb(252,232,232));
  int ng=checks.Count(c=>!c.Ok);r.Paragraph(ng==0?"All checks are satisfied for the load cases given.":ng+" check(s) are NOT satisfied - revise the footing sizes, eccentricities, straps or reinforcement.",false,true);
  r.Signatures("Prepared by","Checked by","Approved by");
  r.Heading("9  NOTES AND LIMITATIONS");foreach(var n in notes)r.Paragraph("• "+n);r.Paragraph("• Prepared with DTCE Tool Kit; the program does not approve the design. Valid only when checked and signed by the responsible engineer.",true);
  return r.Build();}
 protected override string BuildReport(){var inp=Input();string unit;var rows=Rows(out unit);var notes=new List<string>();var cases=StrapFooting.Cases(inp,rows,notes);var steps=new Dictionary<SupportCheck,List<string>>();var checks=StrapFooting.Check(inp,cases,notes,steps);var b=new StringBuilder();
  b.AppendLine("STRAP FOUNDATION - DESIGN CALCULATION");b.AppendLine();b.AppendLine("## 01  CHECKS");foreach(var c in checks)b.AppendLine(c.Name+" ["+c.Clause+"] "+c.Node+" "+c.Case+": "+StrapFooting.F(c.Demand,"0.0")+" / "+StrapFooting.F(c.Capacity,"0.0")+" "+c.Unit+" = "+StrapFooting.F(c.Ratio,"0.00")+" "+(c.Ok?"OK":"NG"));b.AppendLine();b.AppendLine("## 02  NOTES");foreach(var n in notes)b.AppendLine("- "+n);return b.ToString();}
